'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),{spawn}=require('child_process'),express=require('express'),multer=require('multer');
const{DATA_DIR,APP_DIR}=require('./paths'),{db}=require('./db'),{encrypt,decrypt}=require('./crypto');
const runtime=path.join(APP_DIR,'vendor/media/node_modules'),ffmpeg=require(path.join(runtime,'ffmpeg-static')).replace(/app\.asar([/\\])/,'app.asar.unpacked$1');let ffprobe=null;try{ffprobe=require(path.join(runtime,'@ffprobe-installer/ffprobe')).path.replace(/app\.asar([/\\])/,'app.asar.unpacked$1')}catch{};
const dir=path.join(DATA_DIR,'videos');fs.mkdirSync(dir,{recursive:true});
db.exec('CREATE TABLE IF NOT EXISTS monday_video_assets(id TEXT PRIMARY KEY,name TEXT,url TEXT,metadata TEXT,created_at TEXT);CREATE TABLE IF NOT EXISTS monday_motion_requests(id TEXT PRIMARY KEY,status TEXT,request_id TEXT,error TEXT,updated_at TEXT);');
const configFile=path.join(DATA_DIR,'motion-control.enc'),model='fal-ai/kling-video/v2.6/standard/motion-control',controllers=new Map();
function config(){try{return JSON.parse(decrypt(fs.readFileSync(configFile,'utf8')))}catch{return {}}}
function configured(){return !!(process.env.FAL_KEY||config().apiKey)}
function client(signal){const key=process.env.FAL_KEY||config().apiKey;if(!key)throw Error('Chưa kết nối Motion Control. Nhập fal.ai API key trong thiết lập node.');return require(path.join(runtime,'@fal-ai/client')).createFalClient({credentials:key,fetch:(input,init={})=>fetch(input,{...init,signal:AbortSignal.any([AbortSignal.timeout(120000),...(signal?[signal]:[]),...(init.signal?[init.signal]:[])])})})}
function managed(url){if(typeof url!=='string'||!/^\/(videos|uploads)\/[\w.-]+$/.test(url))throw Error('Chỉ nhận file ảnh/video đã lưu trên máy');const f=path.join(DATA_DIR,url.slice(1));if(!fs.existsSync(f))throw Error('File đầu vào không còn trên máy');return f}
function command(bin,args,signal){return new Promise((resolve,reject)=>{const p=spawn(bin,args,{signal,stdio:['ignore','pipe','pipe']});let out='',err='';const t=setTimeout(()=>p.kill('SIGKILL'),300000);p.stdout.on('data',b=>out+=b);p.stderr.on('data',b=>err=(err+b).slice(-6000));p.on('error',e=>{clearTimeout(t);reject(e)});p.on('close',code=>{clearTimeout(t);code===0?resolve(out):reject(Error(signal?.aborted?'Đã dừng xử lý video':'Không xử lý được video: '+err.slice(-350)))})})}
async function probe(file){if(!ffprobe)throw Error('Chức năng phân tích video cần ffprobe; trợ lý prompt vẫn hoạt động bình thường.');const d=JSON.parse(await command(ffprobe,['-v','error','-show_format','-show_streams','-of','json',file]));const v=d.streams.find(s=>s.codec_type==='video');const duration=Number(d.format?.duration||v?.duration);if(!v||!Number.isFinite(duration)||duration<=0)throw Error('File không có luồng video hợp lệ');return {duration,width:v.width,height:v.height,audio:d.streams.some(s=>s.codec_type==='audio')}}
const router=express.Router();router.get('/assets',(_,res)=>res.json(db.prepare('SELECT * FROM monday_video_assets ORDER BY created_at DESC LIMIT 100').all().map(r=>({...r,...JSON.parse(r.metadata)}))));
const upload=multer({dest:dir,limits:{fileSize:200*1024*1024,files:1}}).single('file');
router.post('/upload',(req,res)=>upload(req,res,async err=>{if(err)return res.status(400).json({error:'Video tối đa 200 MB'});if(!req.file)return res.status(400).json({error:'Chọn một video'});let target=req.file.path;try{const meta=await probe(target);if(meta.duration>30.05)throw Error('Video nguồn tối đa 30 giây. Cắt clip trước khi tải.');const id=crypto.randomUUID(),name='source_'+id+'.mp4',final=path.join(dir,name);target=final;await command(ffmpeg,['-y','-i',req.file.path,'-map','0:v:0','-map','0:a:0?','-vf',"scale=w='min(1920,iw)':h='min(1920,ih)':force_original_aspect_ratio=decrease:force_divisible_by=2",'-c:v','libx264','-preset','fast','-crf','19','-pix_fmt','yuv420p','-c:a','aac','-movflags','+faststart',final]);fs.unlinkSync(req.file.path);target=final;db.prepare('INSERT INTO monday_video_assets VALUES(?,?,?,?,?)').run(id,String(req.file.originalname).slice(0,160),'/videos/'+name,JSON.stringify(meta),new Date().toISOString());res.status(201).json({id,name:req.file.originalname,url:'/videos/'+name,...meta})}catch(e){try{fs.unlinkSync(target)}catch{}try{fs.unlinkSync(req.file.path)}catch{}res.status(400).json({error:e.message})}}));
router.get('/motion/config',(_,res)=>res.json({configured:!!(process.env.FAL_KEY||config().apiKey),provider:'fal.ai',model,maxDuration:30,orientationLimits:{image:10,video:30}}));
router.put('/motion/config',(req,res)=>{const key=String(req.body.apiKey||'').trim();if(key.length<10||key.length>512||/\s/.test(key))return res.status(400).json({error:'API key không hợp lệ'});const tmp=configFile+'.tmp';fs.writeFileSync(tmp,encrypt(JSON.stringify({apiKey:key})),{mode:0o600});fs.renameSync(tmp,configFile);res.json({configured:true})});
router.delete('/motion/config',(_,res)=>{try{fs.unlinkSync(configFile)}catch{}res.json({configured:!!process.env.FAL_KEY})});
function asset(id){const r=db.prepare('SELECT * FROM monday_video_assets WHERE id=?').get(id);if(!r)throw Error('Chọn video nguồn hợp lệ');managed(r.url);return {url:r.url,mediaType:'video',...JSON.parse(r.metadata)}}
async function combine(key,inputs,node){const ctrl=new AbortController();controllers.set(key,ctrl);const temp=path.join(dir,'combine_work_'+crypto.randomUUID());fs.mkdirSync(temp);const out=path.join(dir,'video_combine_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,20)+'.mp4');try{const clips=Object.keys(inputs).filter(h=>/^clip[1-9]\d*$/.test(h)).sort((a,b)=>Number(a.slice(4))-Number(b.slice(4))).map(h=>inputs[h]);if(clips.length<2)throw Error('Cần ít nhất 2 clip');const ratio=node.data.ratio||'16:9',[w,h]=ratio==='9:16'?[1080,1920]:ratio==='1:1'?[1080,1080]:[1920,1080];for(let i=0;i<clips.length;i++){const file=managed(clips[i].url),meta=await probe(file);if(meta.duration>10.1)throw Error('Mỗi clip ghép tối đa 10 giây');const args=['-y','-i',file];if(!meta.audio)args.push('-f','lavfi','-i','anullsrc=channel_layout=stereo:sample_rate=48000');args.push('-map','0:v:0','-map',meta.audio?'0:a:0':'1:a:0','-vf',`scale=${w}:${h}:force_original_aspect_ratio=decrease,pad=${w}:${h}:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30`,'-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-c:a','aac','-ar','48000','-ac','2','-t',String(meta.duration),'-threads','2',path.join(temp,i+'.mp4'));await command(ffmpeg,args,ctrl.signal)}fs.writeFileSync(path.join(temp,'list.txt'),clips.map((_,i)=>`file '${i}.mp4'`).join('\n'));await command(ffmpeg,['-y','-f','concat','-safe','1','-i',path.join(temp,'list.txt'),'-c','copy','-movflags','+faststart',out],ctrl.signal);const meta=await probe(out);return {url:'/videos/'+path.basename(out),mediaType:'video',...meta}}catch(e){try{fs.unlinkSync(out)}catch{}throw e}finally{controllers.delete(key);fs.rmSync(temp,{recursive:true,force:true})}}
async function motion(key,inputs,node){const image=managed(inputs.base?.url),video=managed(inputs.motion?.url),meta=await probe(video);const options=require('./motionSpec.cjs').motionOptions(node.data,meta.duration);const ctrl=new AbortController(),fal=client(ctrl.signal);controllers.set(key,ctrl);let row=db.prepare('SELECT * FROM monday_motion_requests WHERE id=?').get(key);try{if(row&&!row.request_id)throw Error('Lần gửi trước chưa xác nhận. Kiểm tra lịch sử fal.ai trước khi Run lại để tránh tính phí trùng.');if(!row){db.prepare('INSERT INTO monday_motion_requests VALUES(?,?,?,?,?)').run(key,'submitting',null,null,new Date().toISOString());const image_url=await fal.storage.upload(new Blob([fs.readFileSync(image)],{type:image.endsWith('.png')?'image/png':image.endsWith('.webp')?'image/webp':'image/jpeg'}));const video_url=await fal.storage.upload(new Blob([fs.readFileSync(video)],{type:'video/mp4'}));if(ctrl.signal.aborted)throw Error('Đã dừng');const submitted=await fal.queue.submit(model,{input:{image_url,video_url,...options,prompt:[inputs.prompt?.text,node.data.text].filter(Boolean).join('\n'),enable_safety_checker:true},abortSignal:ctrl.signal});row={request_id:submitted.request_id};db.prepare('UPDATE monday_motion_requests SET status=?,request_id=?,updated_at=? WHERE id=?').run('queued',row.request_id,new Date().toISOString(),key);if(ctrl.signal.aborted){await fal.queue.cancel(model,{requestId:row.request_id});throw Error('Đã dừng Motion Control')}}const deadline=Date.now()+30*60*1000;while(Date.now()<deadline){if(ctrl.signal.aborted)throw Error('Đã dừng Motion Control');const status=await fal.queue.status(model,{requestId:row.request_id,logs:false});if(status.status==='COMPLETED')break;await new Promise((resolve,reject)=>{const abort=()=>{clearTimeout(t);reject(Error('Đã dừng'))};const t=setTimeout(()=>{ctrl.signal.removeEventListener('abort',abort);resolve()},4000);ctrl.signal.addEventListener('abort',abort,{once:true})})}if(Date.now()>=deadline)throw Error('Motion Control quá thời gian. Yêu cầu vẫn được lưu tại fal.ai; không tự gửi lại.');const result=await fal.queue.result(model,{requestId:row.request_id});const url=new URL(result.data?.video?.url);if(url.protocol!=='https:'||!(/(^|\.)fal\.media$/.test(url.hostname)||/(^|\.)fal\.ai$/.test(url.hostname)))throw Error('Địa chỉ kết quả không được hỗ trợ');const response=await fetch(url,{signal:AbortSignal.any([ctrl.signal,AbortSignal.timeout(120000)]),redirect:'error'});if(!response.ok)throw Error('Không tải được video kết quả');const file=path.join(dir,'video_motion_'+crypto.createHash('sha256').update(key).digest('hex').slice(0,20)+'.mp4');const fd=fs.openSync(file+'.tmp','w');let bytes=0;try{for await(const chunk of response.body){bytes+=chunk.length;if(bytes>200*1024*1024)throw Error('Video kết quả vượt 200 MB');fs.writeSync(fd,chunk)}}finally{fs.closeSync(fd)}fs.renameSync(file+'.tmp',file);const output=await probe(file);db.prepare('UPDATE monday_motion_requests SET status=? WHERE id=?').run('completed',key);return {url:'/videos/'+path.basename(file),mediaType:'video',...output}}catch(e){throw Error(e.status===401?'fal.ai từ chối API key':e.status===402?'fal.ai chưa đủ số dư':e.status?'Motion Control lỗi từ fal.ai (HTTP '+e.status+'). Xem lịch sử yêu cầu tại fal.ai.':e.message)}finally{controllers.delete(key)}}
function cancel(key){controllers.get(key)?.abort();const row=db.prepare('SELECT request_id FROM monday_motion_requests WHERE id=?').get(key);if(row?.request_id)try{client().queue.cancel(model,{requestId:row.request_id}).catch(()=>{})}catch{}}
module.exports={configured,router,asset,probe,combine,motion,cancel,managed,ffmpeg,ffprobe};
